403	+import { HyperlinkButton, useEditor, useValue, TLShapeId } from "tldraw";
404	+import { getTextShapeLinkUrl } from "~/components/canvas/utils/textShapeLink";
405	+
406	+// Matches tldraw's own HyperlinkButton, which hides itself when zoomed out.
407	+const HIDE_BELOW_ZOOM = 0.32;
408	+
409	+type TextLink = { id: TLShapeId; url: string; left: number; top: number };
410	+
411	+// Rendered here, not on a custom shape util, so the stock text shape stays
412	+// untouched -- at the cost of rotation, frame clipping and stacking fidelity.
413	+export const TextLinkOverlay = () => {
414	+  const editor = useEditor();
415	+
416	+  const links = useValue<TextLink[]>(
417	+    "textShapeLinks",
418	+    () => {
419	+      if (editor.getZoomLevel() < HIDE_BELOW_ZOOM) return [];
420	+      const viewport = editor.getViewportPageBounds();
421	+      return editor.getCurrentPageShapes().flatMap<TextLink>((shape) => {
422	+        if (shape.type !== "text" || editor.isShapeHidden(shape)) return [];
423	+        const url = getTextShapeLinkUrl(shape);
424	+        if (!url) return [];
425	+        const bounds = editor.getShapePageBounds(shape.id);
426	+        if (!bounds || !viewport.includes(bounds)) return [];
427	+        const topRight = editor.pageToViewport({
428	+          x: bounds.maxX,
429	+          y: bounds.minY,
430	+        });
431	+        const bottomRight = editor.pageToViewport({
432	+          x: bounds.maxX,
433	+          y: bounds.maxY,
434	+        });
435	+        return [
436	+          {
437	+            id: shape.id,
438	+            url,
439	+            left: topRight.x,
440	+            top: (topRight.y + bottomRight.y) / 2,
441	+          },
442	+        ];
443	+      });
444	+    },
445	+    [editor],
446	+  );
447	+
448	+  return (
449	+    <div className="dg-text-link-overlay">
450	+      {links.map(({ id, url, left, top }) => (
451	+        <div
452	+          key={id}
453	+          className="dg-text-link-anchor"
454	+          style={{ left: `${left}px`, top: `${top}px` }}
455	+        >
456	+          <HyperlinkButton url={url} />
457	+        </div>
458	+      ))}
459	+    </div>
460	+  );
461	+};
